      when(connected, [
        stack({ id: "mui", width: side * 0.6, height: side * 0.6, motion: "none" },
          ["o", "b", "l", "w", "p", "k"].map((letter) =>
            path({ id: `mui-${letter}`, d: pixels(letter), fill: palette[letter], viewBox: "0 0 16 16", width: side * 0.6, height: side * 0.6,
                   motion: "none" }))),
