        path({ id: "word", d: letters, stroke: ink, strokeWidth: 6, width: side, height: side, motion: "none" }),
        path({ id: "dot", d: dot, fill: ink, width: side, height: side, motion: "none" }),
      ]),
    ]),
  ]),
]);

